    @Override void locationDialog(String name,int danger){boolean discovered=db.world().isDiscovered(name);LinearLayout box=col();box.setPadding(dp(18),dp(12),dp(18),dp(6));box.addView(serif(discovered?name:"Neatrasta kryptis",23,PARCH,true));box.addView(txt("GRĖSMĖ "+danger+"/10"+(discovered?" · "+faction(name):" · FRAKCIJA NEŽINOMA"),9,dangerColor(danger),true),sp(dp(8)));box.addView(txt(discovered?lore(name):"Atlasas rodo tik apytikrę kryptį. Pirmiausia reikia surinkti kelio žymes, gandus arba atlikti saugų žvalgymą.",12,Color.rgb(218,223,218),false),sp(dp(8)));int minutes=db.world().travelMinutes(state.location,name);if(discovered&&minutes>0)box.addView(txt("NUMATOMAS KELIONĖS LAIKAS · "+minutes+" pasaulio min.",9,GOLD2,true),sp(dp(6)));new AlertDialog.Builder(this).setView(box).setNegativeButton("UŽDARYTI",null).setPositiveButton(discovered?"KELIAUTI":"TIRTI KRYPTĮ",(d,w)->{show("game");act(discovered?"Keliauti iš "+state.location+" į "+name+" saugiausiu pagrįstu maršrutu, įvertinant laiką ir realias pasekmes.":"Saugiai tirti neatrastą kryptį link "+name+", rinkti kelio žymes ir nekeliauti aklai.");}).show();}
