    View step(boolean done,boolean active,String s){LinearLayout r=row();r.setPadding(0,dp(5),0,dp(5));r.addView(txt(done?"✓":active?"◆":"○",12,done?Color.rgb(105,184,127):active?GOLD2:Color.rgb(102,122,128),true),new LinearLayout.LayoutParams(dp(28),-2));r.addView(txt(s,10,active?PARCH:SUB,active),new LinearLayout.LayoutParams(0,-2,1));return r;}
