    boolean pref(String k,boolean d){return getSharedPreferences("vaeloria_visual",MODE_PRIVATE).getBoolean(k,d);}void haptic(){if(pref("haptics",true)&&root!=null)root.performHapticFeedback(Build.VERSION.SDK_INT>=30?HapticFeedbackConstants.CONFIRM:HapticFeedbackConstants.KEYBOARD_TAP);}void sound(boolean action){if(audio!=null){audio.cue(action?VaeloriaAudio.Cue.ACTION:VaeloriaAudio.Cue.NAVIGATE);return;}if(!pref("sounds",false))return;if(tone==null)tone=new ToneGenerator(AudioManager.STREAM_MUSIC,18);tone.startTone(action?ToneGenerator.TONE_PROP_ACK:ToneGenerator.TONE_PROP_BEEP,45);}int dangerColor(int d){if(pref("colorblind",false))return d>=8?Color.rgb(215,82,150):d>=6?Color.rgb(226,137,45):d>=4?Color.rgb(76,145,210):Color.rgb(79,178,151);return d>=8?Color.rgb(225,93,77):d>=6?Color.rgb(231,144,77):d>=4?GOLD2:Color.rgb(99,187,137);}String faction(String l){String s=l.toLowerCase(Locale.ROOT);return s.contains("kharad")||s.contains("drakono")||s.contains("pelen")?"DRAVENN":s.contains("safyro")||s.contains("slėn")||s.contains("pelkyn")||s.contains("labir")?"LYSARA":"ASTERRA";}
    void locationHub(){ScrollView sv=new ScrollView(this);LinearLayout c=col();c.setPadding(dp(14),dp(12),dp(14),dp(10));sv.addView(c);ImageView art=image(R.drawable.scene_luminara);c.addView(art,new LinearLayout.LayoutParams(-1,dp(130)));c.addView(serif("LUMINARA",22,PARCH,true),sp(dp(2)));c.addView(txt("Asterros sostinė · Meridiano vartų mazgas",9,SUB,false),sp(dp(9)));c.addView(section("ŽINOMOS VIETOS"));for(String place:new String[]{"Meridiano vartai","Didžioji akademija","Žibinto poilsio užeiga","Centrinė rinka","Rezonanso dirbtuvės"}){Button b=dark(place);b.setOnClickListener(v->act("Vykti į "+place+" Luminara mieste ir ištirti situaciją."));c.addView(b,sp(dp(4)));}c.addView(section("ŽMONĖS"),sp(dp(3)));for(String[] n:NPCS)c.addView(npcCard(n),sp(dp(5)));new AlertDialog.Builder(this).setView(sv).setNegativeButton("UŽDARYTI",null).show();}
    View npcCard(String[] n){LinearLayout r=row();r.setGravity(Gravity.CENTER_VERTICAL);r.setPadding(dp(9),dp(7),dp(9),dp(7));r.setBackground(round(Color.rgb(11,22,29),12,Color.rgb(40,57,65)));NpcPortraitV070 i=new NpcPortraitV070(this);i.setNpc(n[0],n[1]);r.addView(i,new LinearLayout.LayoutParams(dp(58),dp(68)));LinearLayout t=col();t.setPadding(dp(10),0,0,0);t.addView(serif(n[0],15,PARCH,true));t.addView(txt(n[1],9,SUB,false));r.addView(t,new LinearLayout.LayoutParams(0,-2,1));r.setOnClickListener(v->npcDialog(n));return r;}void npcDialog(String[] n){LinearLayout c=col();c.setPadding(dp(16),dp(12),dp(16),dp(8));NpcPortraitV070 portrait=new NpcPortraitV070(this);portrait.setNpc(n[0],n[1]);c.addView(portrait,new LinearLayout.LayoutParams(-1,dp(220)));c.addView(serif(n[0],22,PARCH,true),sp(dp(3)));c.addView(txt(n[1].toUpperCase(Locale.ROOT),8,GOLD2,true),sp(dp(8)));c.addView(txt(n[2],11,Color.rgb(217,222,217),false));new AlertDialog.Builder(this).setView(c).setNegativeButton("UŽDARYTI",null).setPositiveButton("KLAUSTI APIE MERIDIANĄ",(d,w)->act("Pasikalbėti su "+n[0]+" apie Lūžusį Meridianą ir išgirsti tik tai, ką šis žmogus realiai žino.")).show();}
